#include <stdio.h>
/* ex03：SPOOLing（假脱机）——用磁盘把独占设备虚拟成共享设备
 * 打印机同一时刻只能服务一个作业，SPOOLing 把「打印请求」先写到磁盘的
 * 输出井（队列），再由守护进程按顺序真正打印。
 * 效果：n 个进程几乎同时拿到「打印已完成」的返回（实际是入队完成）。*/
typedef struct { const char *job; int pages; } Job;

int main(void) {
    Job jobs[] = {{"报表A", 3}, {"报表B", 1}, {"报表C", 5}, {"报表D", 2}};
    int n = (int)(sizeof(jobs) / sizeof(jobs[0]));
    double print_per_page = 0.5;    /* 打印机每页 0.5s */
    double enqueue_cost = 0.05;     /* 写入输出井的耗时 */

    printf("直接独占打印（进程必须等打印机空闲）\n");
    printf("%-10s %-8s %-14s %s\n", "作业", "页数", "开始打印时刻", "完成时刻");
    double t = 0;
    for (int i = 0; i < n; i++) {
        double start = t;
        t += jobs[i].pages * print_per_page;
        printf("%-10s %-8d %-14.2f %.2f\n", jobs[i].job, jobs[i].pages, start, t);
    }
    printf("平均等待+打印 = %.2fs（最后一个作业等最久）\n\n", t / n);

    printf("SPOOLing 假脱机（先入输出井，立即可返回）\n");
    printf("%-10s %-8s %-14s %s\n", "作业", "页数", "入队返回时刻", "实际打印完成");
    t = 0;
    double print_t = 0;
    for (int i = 0; i < n; i++) {
        t += enqueue_cost;                       /* 进程只等入队 */
        double ret = t;
        print_t += jobs[i].pages * print_per_page;
        printf("%-10s %-8d %-14.2f %.2f\n", jobs[i].job, jobs[i].pages, ret, print_t);
    }
    printf("结论：SPOOLing 把「独占设备的等待」转成「磁盘队列的等待」，\n");
    printf("      用户体验从「等打印机」变成「立刻返回」，代价是要磁盘空间与额外拷贝。\n");
    printf("      今天所有打印服务、邮件队列、甚至 Kafka 削峰都是同一思路。\n");
    return 0;
}
